 const lineCount=(game.players||[]).filter(entry=>entry.position!=='Goleiro').length;
 if(lineCount===18){game.teamsEdited=false;autoDistributeGameTeams(game);return}
 if(!game.teamsEdited){autoDistributeGameTeams(game);return}
 if(lineCount>=18&&game.teams.length<3)game.teams.push(structuredClone(thirdTeamTemplate));
 const key=playerKey(player.name);
 if(game.teams.some(team=>teamPlayerNames(team).some(name=>playerKey(name)===key)||(team.playerIds||[]).includes(player.id)))return;
