function adminWeeklyRoster(g){
 if(!g)return '';
 const teams=(g.teams||[]).slice(0,3),rows=(g.players||[]).map((p,index)=>({...p,signupNumber:index+1,teamIndex:gameTeamIndex(g,p)}));
 const panels=teams.map((team,index)=>{const members=rows.filter(p=>p.position!=='Goleiro'&&p.teamIndex===index);const keepers=rows.filter(p=>p.position==='Goleiro'&&p.teamIndex===index);return '<section class="weekly-team-card team-color-'+(index+1)+'"><div class="weekly-team-head"><strong>'+esc(team.name||'TIME 0'+(index+1))+'</strong><span>'+members.length+' jogadores</span></div><div class="week-roster">'+(members.length?members.map(p=>'<div class="week-player"><span class="number">'+String(p.signupNumber).padStart(2,'0')+'</span><span>'+esc(p.name)+'</span><small>Jogador</small></div>').join(''):'<div class="team-empty">Aguardando divisão dos administradores.</div>')+'</div>'+(keepers.length?'<div class="weekly-goalkeepers"><b>Goleiro</b>'+keepers.map(p=>'<div class="week-player"><span class="number">G'+p.signupNumber+'</span><span>'+esc(p.name)+'</span><small>Goleiro</small></div>').join('')+'</div>':'')+'</section>'});
 const waiting=rows.filter(p=>p.teamIndex<0);
 return '<div class="weekly-team-grid">'+panels.join('')+(waiting.length?'<section class="weekly-team-card team-color-waiting"><div class="weekly-team-head"><strong>Aguardando divisão</strong><span>'+waiting.length+' inscritos</span></div><div class="week-roster">'+waiting.map(p=>'<div class="week-player"><span class="number">'+String(p.signupNumber).padStart(2,'0')+'</span><span>'+esc(p.name)+'</span><small>'+esc(p.position||'Jogador')+'</small></div>').join('')+'</div></section>':'')+'</div>';
}
function gameStatus(g){if(g.status==='closed')return '<span class="pill done">Encerrado</span>';if(g.status==='played')return '<span class="pill done">Realizado</span>';return '<span class="pill open">Inscrições abertas</span>'}
function navItem(id,icon,label){return `<button class="${page===id?'active':''}" data-page="${id}"><span class="ico">${icon}</span>${label}</button>`}
function pageTitle(){return ({dashboard:'Visão geral',games:'Jogos',teams:'Times',players:'Participantes',fields:'Gramados',finance:'Pagamentos',polls:'Enquetes',notices:'Avisos',settings:'Configurações'})[page]||'Visão geral'}
function heading(eyebrow,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="sub">${esc(description)}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function stat(label,value,foot,icon='•'){return `<article class="card"><div class="stat-top"><span>${esc(label)}</span><span class="stat-icon">${esc(icon)}</span></div><div class="stat-num">${esc(value)}</div><div class="stat-foot">${esc(foot)}</div></article>`}
function financePage(){const games=state.games.slice().sort((a,b)=>a.date.localeCompare(b.date));const selected=games.find(g=>g.id===rosterGame)||upcoming()||games[0];return `${heading('CONTROLE FINANCEIRO','Pagamentos','Confirme pagamentos recebidos por PIX e confira os valores por jogo.',`<button class="btn" data-action="export">Exportar CSV</button>`)}<div class="panel"><div class="toolbar"><label for="finance-game"><b>Jogo</b></label><select id="finance-game" class="search">${games.map(g=>`<option value="${esc(g.id)}" ${selected?.id===g.id?'selected':''}>${localDate(g.date)} · ${esc(g.time)} · ${esc(field(g.fieldId)?.name||'Gramado')}</option>`).join('')}</select><button class="btn small" data-action="copy-pix">Copiar PIX · ${esc(formatPix(state.pix))}</button></div>${selected?`<div class="payment-legend"><span>${brl(selected.fee)} por jogo${selected.foodFee?` · ${brl(selected.foodFee)} ${esc(selected.foodName||'churrasco')}`:''}</span><span>${selected.date>today?'R$ 0 em aberto até a data do jogo':brl(dueTotal(selected))+' em aberto'}</span></div><div class="week-payments">${selected.players.slice().sort((a,b)=>Number(b.paid)-Number(a.paid)||(String(a.paidAt||'9999').localeCompare(String(b.paidAt||'9999')))).map(p=>{const index=selected.players.indexOf(p);return `<div class="payment-row"><div class="payment-person"><div class="avatar">${initials(p.name)}</div><div><b>${esc(p.name)}</b><small>${p.position==='Goleiro'?'Goleiro':'Jogador'}</small></div></div><button class="pill ${p.position==='Goleiro'?'done':p.paid?'paid':'pending'}" ${p.position==='Goleiro'?'':'data-action="toggle-pay" data-id="'+esc(selected.id)+'" data-index="'+index+'"'}>${p.position==='Goleiro'?'Isento':p.paid?'Jogo pago ✓':`Jogo · marcar ${brl(selected.fee)}`}</button>${selected.foodFee?(p.foodWanted?`<button class="pill ${p.foodPaid?'paid':'pending'}" data-action="toggle-food" data-id="${esc(selected.id)}" data-index="${index}">Churrasco ${p.foodPaid?'pago ✓':`marcar ${brl(selected.foodFee)}`}</button>`:'<span class="pill done">Churrasco não solicitado</span>'):''}<button class="btn small" data-action="payment" data-id="${esc(selected.id)}" data-index="${index}">Detalhes</button></div>`}).join('')||'<div class="empty">Não há participantes na lista deste jogo.</div>'}</div>`:'<div class="empty">Não há jogos cadastrados.</div>'}</div>`}
function pageBody(g){return ({dashboard:()=>dashboard(g),games:gamesPage,teams:teamsPage,players:playersPage,fields:fieldsPage,finance:financePage,polls:pollsPage,notices:noticesPage,settings:settingsPage}[page]||(()=>dashboard(g)))()}
function render(){
 if(cloudEnabled && !currentUser) return renderLogin();
 if(currentUser?.role==='player') return renderPlayerPage();
 document.querySelector('#app').className='shell';
 const g=upcoming();
 document.querySelector('#app').innerHTML=`<aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">⚽</div><div><strong>Society Gramado</strong><small>Gestão do futebol</small></div></div><div class="nav-label">Menu principal</div><nav class="nav">${navItem('dashboard','▦','Visão geral')}${navItem('games','◷','Jogos')}${navItem('teams','⚑','Times')}${navItem('players','♙','Participantes')}${navItem('fields','▤','Gramados')}${navItem('finance','＄','Pagamentos')}${navItem('polls','☷','Enquetes')}${navItem('notices','▣','Avisos')}${navItem('settings','⚙','Configurações')}</nav><div class="sidebar-bottom"><div class="cloud-status"><span class="cloud-dot" style="background:${cloudEnabled?'#92d85b':'#e9a442'}"></span>${cloudEnabled?'Firebase identificado':'Modo de demonstração'}<br>${cloudEnabled?'Serviços e acesso seguro pendentes':'Os dados ficam neste navegador até configurar o Firebase.'}</div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="btn mobile-menu" id="menuBtn">☰</button> &nbsp; Futebol Society / <b>${pageTitle()}</b></div><div class="user"><div class="avatar">MF</div><span class="user-name">Administrador</span>${cloudEnabled?'<button class="btn small" data-action="logout">Sair</button>':''}</div></header><section class="page">${pageBody(g)}</section></main>`;
}
function renderLogin(message=''){
 const root=document.querySelector('#app');root.className='login-screen';
 if(playerPortalOnly&&currentUser?.role==='admin'){root.innerHTML='<section class="login-card"><div class="brand-mark login-mark">⚽</div><div class="eyebrow">ÁREA DO JOGADOR</div><h1>Este link é exclusivo para jogadores</h1><p class="sub">A sessão atual é de administrador. Para entrar como jogador neste navegador, encerre a sessão administrativa.</p><button class="btn primary login-submit" data-action="switch-to-player">Sair e entrar como jogador</button><a class="btn login-submit" href="./index.html">Abrir painel administrativo</a></section>';return}
 const playerLogin=playerPortalOnly;
 const title=playerLogin?'Área do jogador':'Área administrativa';
 root.innerHTML=`<section class="login-card"><div class="brand-mark login-mark">⚽</div><div class="eyebrow">FUTEBOL SOCIETY</div><h1>Society Gramado</h1><div class="tabs"><span class="tab active">${title}</span></div>${playerLogin?`<p class="sub">Informe seu primeiro nome, nome completo ou apelido. Use os 9 números do celular sem DDD; jogadores sem telefone usam 123456.</p><form id="loginForm" data-kind="player"><label for="playerIdentifier">Primeiro nome, nome completo ou apelido</label><input id="playerIdentifier" name="identifier" autocomplete="username" placeholder="Ex.: Maicon, Manoel Fernandes Neto ou Neto" required><label for="playerPhone">Telefone / senha</label><input id="playerPhone" name="phone" type="tel" inputmode="numeric" autocomplete="current-password" placeholder="9 números sem DDD; provisória: 123456" required><div class="login-error" role="alert">${esc(message)}</div><div class="inline-actions"><button class="btn primary login-submit" name="intent" value="enter" type="submit">Entrar</button><button class="btn login-submit" name="intent" value="request" type="submit">Primeiro acesso</button></div></form><p class="login-foot">Ao entrar ou no primeiro acesso, seu perfil é liberado automaticamente. Use o telefone local, sem DDD e sem +55, como senha.</p>`:`<p class="sub">Entre com o e-mail e a senha do administrador.</p><form id="loginForm" data-kind="admin"><label for="loginEmail">E-mail</label><input id="loginEmail" name="email" type="email" autocomplete="username" required><label for="loginPassword">Senha</label><div class="password-input-row"><input id="loginPassword" name="password" type="password" autocomplete="current-password" required><button class="password-toggle" type="button" data-toggle-password="loginPassword" aria-controls="loginPassword" aria-pressed="false">Mostrar</button></div><div class="login-error" role="alert">${esc(message)}</div><button class="btn primary login-submit" type="submit">Entrar</button></form><p class="login-foot">Acesso restrito ao administrador autorizado.</p>`}</section>`;
}
function watchPollData(playerUid=null){stopPollListener?.();stopPollTalliesListener?.();stopMyPollVotesListener?.();stopPollListener=listenToRecords('polls',rows=>{polls=rows;persistRecords('polls',rows);if(currentUser?.role==='admin')for(const row of rows)if(row.expiresAt&&!Number.isFinite(Number(row.expiresAtMs)))saveRecord('polls',{...row,expiresAtMs:new Date(`${row.expiresAt}T23:59:59.999-03:00`).getTime()}).catch(()=>{});if(currentUser?.role==='player'||page==='polls')render()},()=>toast('Falha ao carregar as enquetes. Confira as regras do Firestore.'));stopPollTalliesListener=listenToRecords('pollTallies',rows=>{pollTallies=rows;if(currentUser?.role==='player'||page==='polls')render()},()=>toast('Falha ao atualizar os resultados das enquetes.'));if(playerUid)stopMyPollVotesListener=listenToMyPollVotes(playerUid,rows=>{myPollVotes=rows;if(currentUser?.role==='player')render()},()=>toast('Falha ao carregar sua resposta das enquetes.'))}
function activePoll(poll){return !poll.expiresAt||poll.expiresAt>=today}
function pollTally(pollId,index){return Number(pollTallies.find(row=>row.id===`${pollId}-${index}`)?.count||0)}
function pollCount(poll,index){return Number(poll.options?.[index]?.votes||0)+pollTally(poll.id,index)}
function playerPollsPanel(){const active=polls.filter(activePoll);return `<section class="panel player-polls" style="margin-top:16px"><div class="panel-head"><div><div class="eyebrow">PARTICIPE</div><h3>Enquetes do grupo</h3></div></div>${active.length?active.map(poll=>{const vote=myPollVotes.find(row=>row.pollId===poll.id),total=poll.options.reduce((sum,_,i)=>sum+pollCount(poll,i),0);return `<article class="notice-item"><div class="field-title">${esc(poll.question)}</div><div class="subcell">${poll.expiresAt?`Até ${localDate(poll.expiresAt)}`:'Sem prazo'} · ${total} voto(s)</div><div class="poll-choices">${poll.options.map((option,index)=>{const count=pollCount(poll,index),selected=Number(vote?.optionIndex)===index;return `<div class="poll-choice"><div class="poll-choice-line"><span>${esc(option.label)}${selected?' · Sua escolha':''}</span><b>${count}</b></div><div class="poll-meter"><i style="width:${total?Math.round(count/total*100):0}%"></i></div>${!vote?`<button class="btn small" data-action="poll-cast-vote" data-id="${esc(poll.id)}" data-index="${index}" ${pollVotesInFlight.has(poll.id)?'disabled':''}>Votar nesta opção</button>`:''}</div>`}).join('')}</div>${vote?'<div class="pill paid" style="margin-top:10px">Resposta registrada ✓</div>':'<div class="subcell" style="margin-top:8px">Você pode responder uma vez por enquete.</div>'}</article>`}).join(''):'<div class="empty">Nenhuma enquete ativa no momento.</div>'}</section>`}
function playerProfilePanel(data){
 return `<section class="panel" style="margin-top:16px"><div class="panel-head"><h3>Meu perfil</h3></div><form id="playerProfileForm"><div class="form-grid"><div class="field"><label for="playerDisplayName">Nome completo</label><input id="playerDisplayName" name="displayName" maxlength="100" value="${esc(data.displayName||data.name||'')}" required></div><div class="field"><label for="playerDisplayNickname">Apelido</label><input id="playerDisplayNickname" name="displayNickname" maxlength="40" value="${esc(data.displayNickname||data.nickname||'')}" placeholder="Como prefere ser chamado"></div></div><button class="btn primary" type="submit">Salvar meu perfil</button><p class="sub">Você pode editar seu nome e apelido. Para corrigir o telefone de acesso, fale com um administrador.</p></form></section>`;
}
function playerGameSelectionPanel(data,game){
 if(!game)return '';
 const info=(data.rosterGames||[]).find(item=>item.id===game.id)||game;
 const stored=data.attendanceChoices?.[game.id],choice=stored&&typeof stored==='object'?stored:{};
 const joined=typeof choice.joined==='boolean'?choice.joined:!!info.joined;
 const foodWanted=typeof choice.foodWanted==='boolean'?choice.foodWanted:!!info.foodWanted;
 const goalkeeper=info.position==='Goleiro',fee=goalkeeper?0:Number(info.fee??game.fee??20),foodFee=Number(info.foodFee??game.foodFee??0);
 return `<section class="panel player-game-selection"><div class="panel-head"><div><div class="eyebrow">JOGO DA SEMANA</div><h3>Confirme sua participação</h3></div><span class="subcell">${localDate(info.date||game.date)} · ${esc(info.time||game.time||'')}</span></div><div class="player-choice-grid"><label class="player-choice-option"><input class="player-game-choice" type="checkbox" data-player-game-choice="joined" data-game-id="${esc(game.id)}" ${joined?'checked':''}><span><b>Vou jogar</b><small>${goalkeeper?'Goleiro · isento da taxa do jogo':brl(fee)+' · taxa do jogo'}</small></span></label><label class="player-choice-option ${!joined?'choice-disabled':''}"><input class="player-game-choice" type="checkbox" data-player-game-choice="foodWanted" data-game-id="${esc(game.id)}" ${foodWanted?'checked':''} ${!joined||!foodFee?'disabled':''}><span><b>Quero churrasco</b><small>${foodFee?brl(foodFee)+' · pagamento separado': 'Não há churrasco cadastrado'}</small></span></label></div><p class="sub">Sua escolha entra na lista da semana. O administrador pode ajustar a inscrição e o churrasco.</p></section>`;
}
function renderPlayerPage(){const data=currentPlayerData,allGames=data?.games||[],current=upcoming(),games=allGames.filter(g=>g.id===current?.id),publicRoster=sharedGameRosters.find(item=>item.id===current?.id),awardGame=allGames.find(g=>g.date===today)||games[0],due=games.reduce((sum,g)=>sum+(g.date>today?0:(g.position==='Goleiro'||g.paid?0:Number(g.fee||0))+(g.foodFee&&!g.foodPaid?Number(g.foodFee):0)),0);document.querySelector('#app').className='player-view';document.querySelector('#app').innerHTML=`<main class="player-page"><header class="player-head"><div><div class="eyebrow">ÁREA DO JOGADOR</div><h1>Olá, ${esc(data?.displayName||data?.name||pendingPlayerIdentity?.firstName||'jogador')}!</h1></div><button class="btn" data-action="logout">Sair</button></header>${data?`${playerGameSelectionPanel(data,current)}<div class="cards">${stat('Você deve',brl(due),'Débito somente na semana do jogo','＄')}${stat('Jogos na lista',games.length,'Partidas vinculadas a você','⚽')}${stat('Chave PIX',formatPix(data.pix)||'—','Pagamento via PIX','▣')}${stat('Acesso','Ativo','Conta aprovada pelo administrador','✓')}</div><div class="panel"><div class="panel-head"><h3>Seus jogos e pagamentos</h3><button class="btn small" data-action="copy-player-pix">▣ Copiar PIX</button></div>${games.length?`<div class="table-wrap"><table class="player-payments-table"><thead><tr><th>Data e local</th><th>Jogo</th><th>Churrasco</th><th>Sua presença</th><th>Débito da semana</th></tr></thead><tbody>${games.map(g=>{const owed=(g.paid?0:g.fee)+(g.foodFee&&!g.foodPaid?g.foodFee:0);return `<tr><td class="name-cell" data-label="Data e local">${localDate(g.date)}<div class="subcell">${esc(g.time)} · ${esc(g.field)}</div><div class="subcell">${playerFieldLinks(g)}</div></td><td data-label="Pagamento do jogo"><span class="pill ${g.position==='Goleiro'?'done':g.paid?'paid':'pending'}">${g.position==='Goleiro'?'Isento':g.paid?'Pg':'Pendente'}</span></td><td data-label="Churrasco">${g.foodFee?`<span class="pill ${g.foodPaid?'paid':'pending'}">${g.foodPaid?'Pg':'Pendente'}</span>`:'—'}</td><td data-label="Disponibilidade"><select class="inline-select player-attendance" data-player-game="${esc(g.id)}"><option value="friday" ${(g.attendance||'friday')==='friday'?'selected':''}>Sexta · participo</option><option value="saturday" ${g.attendance==='saturday'?'selected':''}>Só sábado se chover</option></select></td><td data-label="Débito">${g.date>today?'—':`<b>${brl(owed)}</b>`}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">Ainda não há jogos vinculados ao seu cadastro.</div>`}<div class="note">Depois de fazer o PIX, envie o comprovante ao administrador para que ele confirme o pagamento no sistema. Chave PIX: <b>${esc(formatPix(data.pix))}</b>. Sua escolha de disponibilidade será registrada na lista do administrador.</div></div>${playerProfilePanel(data)}${playerAwardPanel(awardGame)}${playerPollsPanel()}<section class="panel" style="margin-top:16px"><div class="panel-head"><h3>Avisos do grupo</h3></div>${notices.filter(n=>!n.expiresAt||n.expiresAt>=today).map(n=>`<article class="notice-item"><div class="field-title">${esc(n.title)}</div><div class="subcell">${n.expiresAt?`Até ${localDate(n.expiresAt)}`:''}</div><p class="sub">${esc(n.message).replaceAll('\n','<br>')}</p>${(n.images||[]).map(src=>`<img class="notice-image" src="${src}" alt="Imagem do aviso">`).join('')}</article>`).join('')||'<div class="empty">Nenhum aviso ativo.</div>'}</section>${playerRosterPanel((publicRoster?.roster?.length||publicRoster?.goalkeepers?.length)?publicRoster:(data?.rosterGames||[]).find(g=>g.id===current?.id)||games[0]||current)}<p class="login-foot">Seu acesso mostra apenas os jogos e pagamentos do seu cadastro.</p>`:`<div class="panel"><h3>Sincronizando seu cadastro</h3><p class="sub">Seu login foi aceito. Estamos carregando seu perfil e os jogos vinculados. Se esta mensagem permanecer por mais de alguns segundos, saia e entre novamente.</p></div>`}</main>`}

function dashboard(g){
 const action=`<button class="btn primary" data-action="new-game">＋ Novo jogo</button>`;
 const local=g?(g.locationLabel||field(g.fieldId)?.name||'A definir'):'Sem jogo cadastrado';
 const payments=g?[...g.players].sort((a,b)=>Number(b.paid)-Number(a.paid)||(a.paid&&b.paid?String(a.paidAt||'9999').localeCompare(String(b.paidAt||'9999')):Number(b.foodWanted&&b.foodPaid)-Number(a.foodWanted&&a.foodPaid))||a.name.localeCompare(b.name,'pt-BR')):[];
 const list=g?.players||[];
 const owed=g?dueTotal(g):0;
 const activeNotices=notices.filter(n=>!n.expiresAt||n.expiresAt>=today);
 const activePolls=polls.filter(p=>!p.expiresAt||p.expiresAt>=today);
 const extras=activeNotices.length||activePolls.length?`<div class="grid-2 dashboard-extras">${activeNotices.length?`<section class="panel"><div class="panel-head"><h3>Avisos ativos</h3><button class="btn small" data-action="new-notice">＋ Aviso</button></div>${activeNotices.map(n=>`<article class="notice-item"><div class="field-title">${esc(n.title)}</div>${n.expiresAt?`<div class="subcell">Até ${localDate(n.expiresAt)}</div>`:''}<p class="sub" style="margin-top:7px">${esc(n.message).replaceAll('\n','<br>')}</p>${(n.images||[]).slice(0,2).map(src=>`<img class="notice-image" src="${src}" alt="Imagem do aviso">`).join('')}<div class="inline-actions" style="margin-top:8px"><button class="btn small" data-action="edit-notice" data-id="${esc(n.id)}">Editar</button><button class="btn small" data-action="delete-notice" data-id="${esc(n.id)}">Excluir</button></div></article>`).join('')}</section>`:''}${activePolls.length?`<section class="panel"><div class="panel-head"><h3>Enquetes ativas</h3><button class="btn small" data-action="new-poll">＋ Enquete</button></div>${activePolls.map(item=>`<article class="notice-item"><div class="field-title">${esc(item.question)}</div><div class="subcell">${item.expiresAt?`Até ${localDate(item.expiresAt)}`:'Sem prazo'}</div>${(item.options||[]).map((option,index)=>`<div class="quick-item"><span>${esc(option.label)}</span><b>${Number(option.votes||0)} voto(s)</b><button class="btn small" data-action="poll-vote" data-id="${esc(item.id)}" data-index="${index}">+1</button><button class="copy" data-action="poll-minus" data-id="${esc(item.id)}" data-index="${index}">−1</button></div>`).join('')}<div class="inline-actions" style="margin-top:8px"><button class="btn small" data-action="edit-poll" data-id="${esc(item.id)}">Editar</button><button class="btn small" data-action="delete-poll" data-id="${esc(item.id)}">Excluir</button></div></article>`).join('')}</section>`:''}</div>`:'';
 return `${heading('PAINEL DO ADMINISTRADOR','Jogo da semana','Partida, lista, pagamentos PIX e comunicados ativos da semana.',action)}<div class="grid-2 dashboard-week"><section class="panel"><div class="panel-head"><h3>Agenda recente</h3>${g?gameStatus(g):''}</div>${g?`<div class="week-summary"><div><span>Jogo</span><b>${localDate(g.date)} · ${esc(g.time)}</b></div><div><span>Local</span><b>${esc(local)}</b></div><div><span>Lista</span><b>${list.filter(p=>p.position!=='Goleiro').length}/21 jogadores de linha · ${list.filter(p=>p.position==='Goleiro').length} goleiros</b></div><div><span>Status</span><b>${esc(g.status==='open'?'Lista aberta':g.status==='closed'?'Lista fechada':'Realizado')}</b></div></div><div class="subcell" style="margin-top:10px">Sessão de ${Number(g.durationMinutes||60)} min · partidas de ${Number(g.matchIntervalMinutes||8)} min · ${g.teams?.length===3?'times com 6–7 + 1':'2 times com 7 + 1'}</div>${g.rainDate?`<div class="note">Se chover: ${localDate(g.rainDate)} · ${esc(field(g.rainFieldId)?.name||'Arena Andrino')} · ${esc(g.rainTime||'14:30')}</div>`:''}<div class="panel-head" style="margin-top:18px"><h3>Lista desta semana</h3><button class="btn small" data-action="roster" data-id="${g.id}">Editar lista</button></div>${list.length?adminWeeklyRoster(g):`<div class="empty">A lista desta semana ainda está vazia.</div>`}<div class="panel-head" style="margin-top:18px"><h3>Times sugeridos</h3><button class="btn small" data-action="edit-teams" data-id="${g.id}">Editar times</button></div><div class="team-suggestions">${(g.teams||defaultTeams).map(team=>`<div class="quick-item"><div><div class="quick-title">${esc(team.name)} <span class="subcell">${teamPlayerNames(team).length} jogadores</span></div><div class="quick-meta">🥅 Goleiro: ${esc(team.goalkeeper||'A definir')} · ${teamPlayerNames(team).map(esc).join(', ')||'Sem escalação'}</div></div></div>`).join('')}</div>`:`<div class="empty">Nenhum jogo desta semana cadastrado.</div>`}</section><section class="panel"><div class="panel-head"><h3>PIX e pagamentos</h3><small>${g?`${brl(owed)} em aberto`:''}</small></div><div class="pix-payment"><div><span>Chave PIX · somente PIX</span><b>${esc(formatPix(state.pix))}</b></div><button class="btn small" data-action="copy-pix">Copiar PIX</button></div>${g?`<div class="payment-legend"><span><i class="dot paid-dot"></i> Pagos primeiro · ordem de confirmação</span><span>${brl(g.fee)} jogo${g.foodFee?` · ${brl(g.foodFee)} ${esc(g.foodName||'churrasco')}`:''}</span></div>${payments.length?`<div class="week-payments">${payments.map((p,i)=>`<div class="payment-row"><div class="payment-person"><div class="avatar">${initials(p.name)}</div><div><b>${esc(p.name)}</b><small>${p.position==='Goleiro'?'Goleiro':'Jogador'}</small></div></div><button class="pill ${p.position==='Goleiro'?'done':p.paid?'paid':'pending'}" ${p.position==='Goleiro'?'':'data-action="toggle-pay" data-id="'+g.id+'" data-index="'+g.players.indexOf(p)+'"'}>${p.position==='Goleiro'?'Isento':p.paid?'Jogo pago ✓':`Jogo · marcar ${brl(g.fee)}`}</button>${g.foodFee?(p.foodWanted?`<button class="pill ${p.foodPaid?'paid':'pending'}" data-action="toggle-food" data-id="${g.id}" data-index="${g.players.indexOf(p)}">Churrasco ${p.foodPaid?'pago ✓':`marcar ${brl(g.foodFee)}`}</button>`:`<span class="pill done">Churrasco não solicitado</span>`):''}</div>`).join('')}</div>`:`<div class="empty">Nenhum jogador na lista para pagamento.</div>`}<div class="payment-total"><span>Pagamentos da semana</span><b>${paidCount(g)} pagos · ${list.filter(p=>p.position!=='Goleiro'&&!p.paid).length} pendentes · ${g.date>today?'R$ 0 em aberto até a data do jogo':brl(owed)+' em aberto'}</b></div><div class="inline-actions" style="margin-top:14px"><button class="btn small" data-action="roster" data-id="${g.id}">Editar lista</button></div>`:`<div class="empty">Adicione o jogo da semana para organizar os pagamentos.</div>`}</section></div>${g?adminAwardPanel(g):''}${extras}`
}
function gamesPage(){const g=upcoming();return `${heading('CALENDÁRIO','Jogo da semana','A lista mostra somente o próximo jogo. A semana seguinte fica disponível a partir de sexta-feira.',`<button class="btn primary" data-action="new-game">＋ Agendar jogo</button>`)}<div class="panel"><div class="panel-head"><h3>${g?'Próximo jogo disponível':'Nenhum próximo jogo'}</h3><small>${g?localDate(g.date):'Agenda encerrada'}</small></div>${g?`<div class="table-wrap"><table><thead><tr><th>Data e hora</th><th>Gramado</th><th>Jogadores</th><th>Valor</th><th>Débito da semana</th><th>Status</th><th>Ações</th></tr></thead><tbody><tr><td class="name-cell">${localDate(g.date)}<div class="subcell">${esc(g.time)}</div>${g.rainDate?`<div class="subcell">Se chover: ${localDate(g.rainDate)} · ${esc(g.rainTime||'14:30')}</div>`:''}</td><td>${esc(g.locationLabel||field(g.fieldId)?.name||'A definir')}${g.rainDate?`<div class="subcell">Chuva: ${esc(field(g.rainFieldId)?.name||'Arena Andrino')}</div>`:''}</td><td>${g.players.length}</td><td>${brl(g.fee)}${g.foodFee?`<div class="subcell">+ ${brl(g.foodFee)} ${esc(g.foodName||'extra')}</div>`:''}</td><td>${g.date>today?'Ainda não vence':brl(dueTotal(g))}</td><td>${gameStatus(g)}</td><td><div class="inline-actions"><button class="btn small" data-action="roster" data-id="${g.id}">Lista</button><button class="btn small" data-action="edit-game" data-id="${g.id}">Editar</button></div></td></tr></tbody></table></div>`:`<div class="empty">Não há jogos futuros cadastrados.</div>`}<div class="note">${fridayWindowOpen()?'A escolha para a próxima semana já está aberta.':'A próxima semana será liberada na sexta-feira, dia do jogo.'} A área do jogador mostra apenas o jogo da semana. O status do pagamento é Pago ou Pendente; débitos só entram no saldo na semana do jogo.</div></div>`}
function playerAccessRequestsPanel(){const pending=accessRequests.filter(r=>r.status==='pending');if(!pending.length)return '';return `<div class="panel" style="margin-bottom:15px"><div class="panel-head"><h3>Pedidos de acesso</h3><small>${pending.length} aguardando</small></div><div class="table-wrap"><table><thead><tr><th>Nome e apelido</th><th>Telefone</th><th>Vincular participante</th><th>Ações</th></tr></thead><tbody>${pending.map(r=>{const requestKeys=new Set([r.firstName,r.fullName,r.nickname].filter(Boolean).flatMap(value=>[value,...String(value).split(/\s+/)]).map(playerKey)),candidates=state.players.filter(p=>p.active&&[p.name,p.nickname,...(p.aliases||[])].filter(Boolean).some(name=>requestKeys.has(playerKey(name))||String(name).split(/\s+/).some(token=>requestKeys.has(playerKey(token))))),exact=candidates.filter(p=>phoneDigits(p.phone)&&playerPhoneMatches(p.phone,r.phone)),defaultMatch=exact.length===1?exact[0]:exact.length===0&&candidates.length===1&&!phoneDigits(candidates[0].phone)?candidates[0]:null;return `<tr><td class="name-cell">${esc(r.fullName||r.firstName)}${r.nickname?`<div class="subcell">Apelido: ${esc(r.nickname)}</div>`:''}</td><td>${esc(r.phone)}</td><td><select class="inline-select" data-request-player="${esc(r.id)}"><option value="">Criar participante novo</option>${state.players.filter(p=>p.active).map(p=>`<option value="${esc(p.id)}" ${defaultMatch?.id===p.id?'selected':''}>${esc(p.name)}${p.phone?` · ${esc(p.phone)}`:''}</option>`).join('')}</select></td><td><div class="inline-actions"><button class="btn small primary" data-action="approve-player" data-id="${esc(r.id)}">Aprovar agora</button><button class="btn small" data-action="edit-access-request" data-id="${esc(r.id)}">Editar</button><button class="btn small" data-action="delete-access-request" data-id="${esc(r.id)}">Excluir</button></div></td></tr>`}).join('')}</tbody></table></div><div class="note">O administrador aprova em um clique. Escolha um participante existente ou mantenha “Criar participante novo”. Depois, o jogador verá apenas seus próprios dados.</div></div>`}
function playersPage(){
 const term=searchTerm.toLocaleLowerCase('pt-BR');
 const list=state.players.filter(p=>p.name.toLocaleLowerCase('pt-BR').includes(term)||(p.nickname||'').toLocaleLowerCase('pt-BR').includes(term)||p.phone.includes(term)||phoneDigits(p.phone).includes(phoneDigits(term))).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR',{sensitivity:'base'}));
 const accessCount=list.filter(p=>{const account=playerAccounts.find(row=>row.playerId===p.id);return !!(account?.approved&&account.loginEmail&&loginAliases.some(alias=>alias.email===account.loginEmail))}).length;
 return `${heading('ELENCO','Participantes','“Ativo” indica presença no elenco. O acesso só fica liberado quando a conta e o apelido de login estão sincronizados.',`<button class="btn" data-action="activate-all-players">Ativar acessos</button><button class="btn primary" data-action="new-player">＋ Adicionar participante</button>`)}${playerBatchReport?`<div class="note">${esc(playerBatchReport)}</div>`:''}<div class="panel"><div class="toolbar"><input class="search" id="search" placeholder="⌕  Buscar por nome ou telefone" value="${esc(searchTerm)}"><small style="color:var(--muted)">${list.length} participantes · ${accessCount} acessos liberados</small></div><div class="table-wrap"><table><thead><tr><th>Participante</th><th>Telefone</th><th>Jogos na lista</th><th>Acesso do jogador</th><th>Ações</th></tr></thead><tbody>${list.map(p=>{const account=playerAccounts.find(row=>row.playerId===p.id),displayName=account?.displayName||p.name,displayNickname=account?.displayNickname||p.nickname,aliasReady=!!(account?.approved&&account.loginEmail&&loginAliases.some(alias=>alias.email===account.loginEmail)),count=state.games.reduce((n,g)=>n+g.players.filter(x=>x.playerId===p.id||x.name.toLowerCase()===p.name.toLowerCase()).length,0);return `<tr><td><div class="person"><div class="avatar">${initials(displayName)}</div><div><div class="name-cell">${esc(displayName)}</div>${displayNickname?`<div class="subcell">Apelido: ${esc(displayNickname)}</div>`:''}</div></div></td><td>${p.phone?`<a class="link" href="https://wa.me/${p.phone.replace(/\D/g,'')}" target="_blank">${esc(displayPhone(p.phone))}</a>`:'—'}</td><td>${count}</td><td><span class="pill ${aliasReady?'paid':'pending'}">${aliasReady?'Liberado':'Pendente'}</span><div class="subcell">${p.active?'Ativo no elenco':'Inativo no elenco'}</div></td><td><div class="inline-actions"><button class="btn small" data-action="edit-player" data-id="${p.id}">Editar</button><button class="btn small" data-action="delete-player" data-id="${p.id}">Excluir</button></div></td></tr>`}).join('')}</tbody></table></div></div>`;
}
function editAccessRequest(req){openModal('Editar pedido de acesso',`<div class="form-grid"><div class="field full"><label>Nome completo</label><input name="fullName" value="${esc(req.fullName||req.firstName)}" required></div><div class="field full"><label>Apelido</label><input name="nickname" value="${esc(req.nickname||'')}"></div></div><div class="note">O primeiro nome e telefone usados para entrar permanecem os informados pelo jogador. Ajuste o telefone de contato no cadastro do participante.</div>`);document.querySelector('#modalForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const updated={...req,fullName:form.elements.fullName.value.trim(),nickname:form.elements.nickname.value.trim()};try{await saveRecord('playerAccessRequests',updated);accessRequests=accessRequests.map(x=>x.id===req.id?updated:x);closeModal();render();toast('Pedido atualizado.')}catch{toast('Não foi possível editar o pedido. Confira as regras do Firestore.')}}}
function fieldsPage(){return `${heading('LOCAIS','Gramados','Endereços e rotas dos jogos. Os administradores podem editar os dados.',`<button class="btn primary" data-action="new-field">＋ Novo gramado</button>`)}<div class="section-grid">${state.fields.map(f=>`<article class="field-card"><div class="field-banner">⚽</div><div class="field-title">${esc(f.name)}</div><div class="field-address">${esc(f.address||'Local do jogo')}</div>${f.notes?`<p class="sub">${esc(f.notes)}</p>`:''}<div class="field-actions"><div class="inline-actions">${f.maps?`<a class="btn small" href="${esc(f.maps)}" target="_blank" rel="noopener">Google Maps ↗</a>`:''}${f.waze?`<a class="btn small" href="${esc(f.waze)}" target="_blank" rel="noopener">Waze ↗</a>`:''}</div><button class="btn small" data-action="edit-field" data-id="${f.id}">Editar</button></div></article>`).join('')}</div>`}
function findTeamPlayer(name){const key=playerKey(name);return state.players.find(p=>[p.name,p.nickname,...(p.aliases||[])].filter(Boolean).some(alias=>playerKey(alias)===key))}
function teamPlayerNames(team){if(Array.isArray(team.playerIds))return team.playerIds.map(id=>state.players.find(p=>p.id===id)?.name).filter(Boolean);return team.players||[]}
function teamsPage(){const games=state.games.slice().sort((a,b)=>a.date.localeCompare(b.date));return `${heading('ESCALAÇÕES','Times','Escolha os jogadores por nome. As escalações usam o cadastro central do elenco.',`<button class="btn" data-action="new-game">＋ Agendar jogo</button>`)}<div class="section-grid">${games.map(g=>`<article class="field-card"><div class="field-title">${localDate(g.date)} · ${esc(g.time)}</div><div class="field-address">${esc(field(g.fieldId)?.name||'Gramado')} · Divisão: ${g.teamAssignmentMode==='random'?'sorteio aleatório':'escolha dos administradores'}</div><div class="team-suggestions">${(g.teams||defaultTeams).map(t=>`<div class="quick-item"><div><div class="quick-title">${esc(t.name)}</div><div class="quick-meta">🥅 Goleiro: ${esc(t.goalkeeper||'A definir')} · ${teamPlayerNames(t).map(esc).join(', ')}</div></div></div>`).join('')}</div><button class="btn small" style="margin-top:12px" data-action="edit-teams" data-id="${g.id}">Editar jogadores dos times</button></article>`).join('')}</div>`}
function teamForm(g){
 const rosterLineCount=(g.players||[]).filter(p=>p.position!=='Goleiro').length;
 if(!g.teamsEdited||(rosterLineCount>=18&&(g.teams||[]).length<3)||(rosterLineCount<18&&(g.teams||[]).length>2)){g.teamsEdited=false;autoDistributeGameTeams(g)}
 const teams=structuredClone(g.teams||defaultTeams).slice(0,3),activePlayers=(g.players||[]).map(entry=>state.players.find(p=>p.id===entry.playerId)||findTeamPlayer(entry.name)).filter(Boolean).slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')),selectedByTeam=[],goalies=[],claimed=new Set();
 if(g.players.filter(p=>p.position!=='Goleiro').length>=18&&teams.length<3)teams.push(structuredClone(thirdTeamTemplate));
 teams.forEach((team,i)=>{const previousNames=teamPlayerNames(team),ids=new Set(Array.isArray(team.playerIds)?team.playerIds:previousNames.map(findTeamPlayer).filter(Boolean).map(p=>p.id)),goalie=findTeamPlayer(team.goalkeeper)?.id||'';goalies[i]=goalie&&!claimed.has(goalie)?goalie:'';if(goalies[i])claimed.add(goalies[i]);selectedByTeam[i]=[...ids].filter(id=>{if(claimed.has(id))return false;claimed.add(id);return true})});
 const teamCards=teams.map((t,i)=>`<div class="panel"><div class="panel-head"><h3>Time ${i+1}</h3><small data-team-count="${i}">${selectedByTeam[i].length}/${teams.length===3?7:Math.ceil(g.players.filter(p=>p.position!=='Goleiro').length/2)} jogadores</small></div><div class="field"><label>Nome do time</label><input name="teamName${i}" value="${esc(t.name)}"></div><div class="field" style="margin-top:10px"><label>Goleiro</label><select name="teamGoalie${i}"><option value="">Escolher goleiro</option>${activePlayers.map(p=>`<option value="${esc(p.id)}" ${goalies[i]===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>Jogadores de linha · ${teams.length===3?"6–7 por time":"distribuídos nos 2 times até 17 inscritos"}</label><input class="search" data-team-filter="${i}" placeholder="⌕ Buscar participante" style="max-width:none;min-width:0;width:100%"><div data-team-picker="${i}" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:7px;max-height:250px;overflow:auto;margin-top:8px;padding:2px">${activePlayers.map(p=>`<label class="team-player-option" data-player-search="${esc(playerKey(p.name+' '+(p.nickname||'')))}" style="display:flex;align-items:center;gap:9px;padding:9px 10px;border:1px solid var(--line);border-radius:10px;cursor:pointer;font-size:12px"><input type="checkbox" name="teamPlayers${i}" value="${esc(p.id)}" ${selectedByTeam[i].includes(p.id)?'checked':''}><span>${esc(p.name)}${p.nickname&&playerKey(p.nickname)!==playerKey(p.name)?`<small style="display:block;color:var(--muted)">${esc(p.nickname)}</small>`:''}</span></label>`).join('')}</div></div></div>`).join('');
 openModal(`Times sugeridos · ${localDate(g.date)}`,`<div class="form-grid">${teamCards}</div><div class="note">Até 17 jogadores de linha, distribua os inscritos nos 2 times, inclusive acima de 7 por time. A partir de 18, o Time 3 é aberto e os jogadores são redistribuídos em 3 times com 6 ou 7 jogadores de linha. Goleiros são contabilizados à parte. Cada sessão dura ${Number(g.durationMinutes||60)} minutos, com partidas de ${Number(g.matchIntervalMinutes||8)} minutos. Ao incluir alguém em um time, ele some das outras listas. Ao salvar, esta escalação é copiada como sugestão para a próxima semana, se ainda não foi editada.</div>`);
 document.querySelector('#modalForm').closest('.modal').style.width='min(900px, 100%)';const form=document.querySelector('#modalForm');const assignmentControl=document.createElement('div');assignmentControl.className='panel team-assignment-control';assignmentControl.innerHTML='<div class="field"><label>Como dividir os inscritos</label><select name="teamAssignmentMode"><option value="manual">Escolha dos administradores</option><option value="random">Sorteio aleatório</option></select></div><button class="btn" type="button" id="randomizeTeams">Sortear inscritos desta semana</button><small>Na escolha manual, os administradores selecionam cada jogador. No sorteio, o app distribui os inscritos entre os times e mantém os números da ordem de inscrição.</small>';form.querySelector('.form-grid').prepend(assignmentControl);form.elements.teamAssignmentMode.value=g.teamAssignmentMode==='random'?'random':'manual';
 const assignedToOther=(playerId,teamIndex)=>teams.some((_,i)=>i!==teamIndex&&(form.elements[`teamGoalie${i}`].value===playerId||form.querySelector(`input[name="teamPlayers${i}"][value="${CSS.escape(playerId)}"]`)?.checked));
 const refreshTeamOptions=()=>{document.querySelectorAll('[data-team-picker]').forEach(picker=>{const i=Number(picker.dataset.teamPicker),term=playerKey(document.querySelector(`[data-team-filter="${i}"]`).value);picker.querySelectorAll('.team-player-option').forEach(label=>{const box=label.querySelector('input'),claimed=assignedToOther(box.value,i)||form.elements[`teamGoalie${i}`].value===box.value;label.hidden=claimed||!label.dataset.playerSearch.includes(term)})});document.querySelectorAll('[name^="teamGoalie"]').forEach(select=>{const i=Number(select.name.replace('teamGoalie',''));[...select.options].forEach(option=>{option.disabled=!!option.value&&assignedToOther(option.value,i)})});teams.forEach((_,i)=>{document.querySelector(`[data-team-count="${i}"]`).textContent=`${document.querySelectorAll(`input[name="teamPlayers${i}"]:checked`).length}/${teams.length===3?7:Math.ceil(g.players.filter(p=>p.position!=='Goleiro').length/2)} jogadores`})};
 document.querySelector('#randomizeTeams').onclick=()=>{const shuffle=items=>{const copy=items.slice();for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy};const unique=items=>[...new Map(items.map(p=>[p.id,p])).values()];const linePlayers=shuffle(unique(g.players.filter(entry=>entry.position!=='Goleiro').map(entry=>state.players.find(player=>player.id===entry.playerId)||findTeamPlayer(entry.name)).filter(Boolean)));const goalkeepers=shuffle(unique(g.players.filter(entry=>entry.position==='Goleiro').map(entry=>state.players.find(player=>player.id===entry.playerId)||findTeamPlayer(entry.name)).filter(Boolean)));form.querySelectorAll('input[name^="teamPlayers"]').forEach(input=>input.checked=false);if(goalkeepers.length)teams.forEach((_,i)=>{document.querySelector('[name="teamGoalie'+i+'"]').value=''});const counts=teams.map(()=>0);let pending=0;for(const player of linePlayers){const maxPerTeam=teams.length===3?7:Math.ceil(g.players.filter(entry=>entry.position!=='Goleiro').length/2);const available=teams.map((_,i)=>i).filter(i=>counts[i]<maxPerTeam);if(!available.length){pending++;continue}const min=Math.min(...available.map(i=>counts[i])),balanced=available.filter(i=>counts[i]===min),teamIndex=balanced[Math.floor(Math.random()*balanced.length)],box=form.querySelector('input[name="teamPlayers'+teamIndex+'"][value="'+CSS.escape(player.id)+'"]');if(box){box.checked=true;counts[teamIndex]++}else pending++}goalkeepers.slice(0,teams.length).forEach((player,i)=>{const select=document.querySelector('[name="teamGoalie'+i+'"]');if(select&&[...select.options].some(option=>option.value===player.id))select.value=player.id});form.elements.teamAssignmentMode.value='random';refreshTeamOptions();toast(pending?'Sorteio feito. '+pending+' inscritos ficaram aguardando uma vaga de time.':'Sorteio concluído. Confira e salve os times.');};document.querySelectorAll('[data-team-filter]').forEach(input=>input.oninput=refreshTeamOptions);
 document.querySelectorAll('[data-team-picker] input[type="checkbox"]').forEach(box=>box.onchange=()=>{const teamIndex=Number(box.name.replace('teamPlayers',''));if(box.checked&&form.elements[`teamGoalie${teamIndex}`].value===box.value){box.checked=false;refreshTeamOptions();return}if(box.checked&&form.querySelectorAll(`input[name="teamPlayers${teamIndex}"]:checked`).length>(teams.length===3?7:Math.ceil(g.players.filter(p=>p.position!=='Goleiro').length/2))){box.checked=false;toast(teams.length===3?'Com 3 times, cada um recebe até 7 jogadores de linha.':'Até 17 inscritos, distribua os jogadores entre os 2 times.');refreshTeamOptions();return}if(box.checked)teams.forEach((_,i)=>{if(i!==teamIndex){const other=form.querySelector(`input[name="teamPlayers${i}"][value="${CSS.escape(box.value)}"]`);if(other)other.checked=false}});refreshTeamOptions()});
 document.querySelectorAll('[name^="teamGoalie"]').forEach(select=>select.onchange=()=>{if(select.value)teams.forEach((_,i)=>{const other=form.querySelector(`input[name="teamPlayers${i}"][value="${CSS.escape(select.value)}"]`);if(other)other.checked=false});refreshTeamOptions()});refreshTeamOptions();
 form.onsubmit=e=>{e.preventDefault();const teamCounts=teams.map((_,i)=>form.querySelectorAll(`input[name="teamPlayers${i}"]:checked`).length),rosterFieldCount=g.players.filter(p=>p.position!=='Goleiro').length;const maxPerTeam=teams.length===3?7:Math.ceil(rosterFieldCount/2);if(teamCounts.some(n=>n>maxPerTeam)){toast(teams.length===3?'Com 3 times, cada um recebe até 7 jogadores de linha.':'Distribua os inscritos entre os 2 times, com no máximo metade arredondada para cima em cada um.');return}if(teamCounts.reduce((sum,count)=>sum+count,0)!==rosterFieldCount){toast('Inclua todos os jogadores inscritos em um dos times.');return}if(teams.length===3&&rosterFieldCount>=18&&teamCounts.some(n=>n<6)){toast('Com 3 times, distribua no mínimo 6 jogadores de linha por time.');return}if(teams.some((_,i)=>!form.elements[`teamGoalie${i}`].value)){toast('Escolha um goleiro para cada time.');return}g.teams=teams.map((t,i)=>{const ids=[...form.querySelectorAll(`input[name="teamPlayers${i}"]:checked`)].map(input=>input.value),goalie=state.players.find(p=>p.id===form.elements[`teamGoalie${i}`].value);return {name:form.elements[`teamName${i}`].value.trim()||`TIME 0${i+1}`,goalkeeper:goalie?.name||'',playerIds:ids,players:ids.map(id=>state.players.find(p=>p.id===id)?.name).filter(Boolean)}});g.teamAssignmentMode=form.elements.teamAssignmentMode.value||'manual';g.teamsEdited=true;const next=nextWeeklyGame(g);if(next&&!next.teamsEdited){next.teams=structuredClone(g.teams);next.teamsSuggestedFrom=g.id}persist();closeModal();render();toast(next&&!next.teamsEdited?'Times salvos e copiados como sugestão para a próxima semana.':'Times atualizados.')}
}
function pollsPage(){return `${heading('INTERAÇÃO','Enquetes','Os jogadores autenticados veem e respondem cada enquete uma vez. Você pode criar, editar e encerrar enquetes.',`<button class="btn primary" data-action="new-poll">＋ Nova enquete</button>`)}<div class="section-grid">${polls.length?polls.map(x=>`<article class="field-card"><div class="field-title">${esc(x.question)}</div><div class="field-address">${x.expiresAt?`Até ${localDate(x.expiresAt)}`:'Sem prazo'} · ${x.options.reduce((sum,_,i)=>sum+pollCount(x.id,i),0)} resposta(s)</div>${(x.options||[]).map((o,i)=>`<div class="quick-item"><span>${esc(o.label)}</span><b>${pollCount(x.id,i)} voto(s)</b><span class="inline-actions"><button class="btn small" data-action="poll-vote" data-id="${esc(x.id)}" data-index="${i}">+1 ajuste</button><button class="copy" data-action="poll-minus" data-id="${esc(x.id)}" data-index="${i}">−1 ajuste</button></span></div>`).join('')}<div class="inline-actions" style="margin-top:12px"><button class="btn small" data-action="edit-poll" data-id="${esc(x.id)}">Editar</button><button class="copy" data-action="delete-poll" data-id="${esc(x.id)}">Excluir</button></div></article>`).join(''):`<div class="panel empty">Ainda não há enquetes.</div>`}</div><div class="note">Os votos dos jogadores são contabilizados automaticamente. Os botões de ajuste servem somente para corrigir contagens antigas.</div>`}
function noticesPage(){const now=today;const active=notices.filter(n=>!n.expiresAt||n.expiresAt>=now);return `${heading('MURAL','Avisos','Publique recados com prazo e até duas imagens. Avisos vencidos são removidos quando o painel administrativo está aberto.',`<button class="btn primary" data-action="new-notice">＋ Novo aviso</button>`)}<div class="section-grid">${active.length?active.map(n=>`<article class="field-card"><div class="field-title">${esc(n.title)}</div><div class="field-address">${n.expiresAt?`Visível até ${localDate(n.expiresAt)}`:'Sem data para expirar'}</div><p class="sub">${esc(n.message).replaceAll('\n','<br>')}</p>${(n.images||[]).map(src=>`<img class="notice-image" src="${src}" alt="Imagem do aviso">`).join('')}<div class="inline-actions" style="margin-top:12px"><button class="btn small" data-action="edit-notice" data-id="${n.id}">Editar</button><button class="copy" data-action="delete-notice" data-id="${n.id}">Excluir</button></div></article>`).join(''):`<div class="panel empty">Nenhum aviso ativo.</div>`}</div>`}
function pollForm(item={}){openModal(item.id?'Editar enquete':'Nova enquete',`<div class="form-grid"><div class="field full"><label>Pergunta *</label><input name="question" required value="${esc(item.question||'')}"></div><div class="field full"><label>Opções (uma por linha) *</label><textarea name="options" rows="5" required>${esc((item.options||[]).map(o=>o.label).join('\n'))}</textarea></div><div class="field"><label>Encerrar em (opcional)</label><input name="expiresAt" type="date" value="${item.expiresAt||''}"></div></div>`);document.querySelector('#modalForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)), options=d.options.split('\n').map((label,i)=>({label:label.trim(),votes:item.options?.[i]?.votes||0})).filter(o=>o.label),rec={id:item.id||`poll-${Date.now()}`,question:d.question.trim(),options,expiresAt:d.expiresAt};if(d.expiresAt)rec.expiresAtMs=new Date(`${d.expiresAt}T23:59:59.999-03:00`).getTime();await saveRecord('polls',rec);polls=[...polls.filter(x=>x.id!==rec.id),rec];persistRecords('polls',polls);closeModal();render();toast('Enquete salva.')}}
async function resizeImage(file){if(!file.type.startsWith('image/'))throw new Error('Use arquivos de imagem.');const img=await createImageBitmap(file);const scale=Math.min(1,1280/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let quality=.78,data=canvas.toDataURL('image/jpeg',quality);while(data.length>330000&&quality>.35){quality-=.1;data=canvas.toDataURL('image/jpeg',quality)}if(data.length>330000)throw new Error('Imagem muito grande mesmo após compressão. Escolha outra.');return data}
function gamePhotos(gameId){return gameGallery.filter(photo=>photo.gameId===gameId).sort((a,b)=>String(a.createdAt||'').localeCompare(String(b.createdAt||'')))}
function galleryMarkup(gameId){const photos=gamePhotos(gameId);return photos.length?`<div class="game-gallery">${photos.map(photo=>`<figure><img src="${esc(photo.image)}" alt="${esc(photo.caption||'Foto do jogo')}"><figcaption>${esc(photo.caption||'Foto do jogo')}</figcaption></figure>`).join('')}</div>`:'<div class="empty compact-empty">As fotos dos times e dos craques aparecerão aqui.</div>'}
function gamePhotoForm(game){const existing=gamePhotos(game.id);openModal(`Fotos do jogo · ${localDate(game.date)}`,`<div class="field"><label>Adicionar fotos (máximo 4 no jogo)</label><input name="images" type="file" accept="image/*" multiple></div>${existing.length?`<div class="game-photo-edit">${existing.map(photo=>`<label><input type="checkbox" name="removePhoto" value="${esc(photo.id)}"><img src="${esc(photo.image)}" alt="${esc(photo.caption||'Foto')}"><span>Remover · ${esc(photo.caption||'Foto')}</span></label>`).join('')}</div>`:''}<div class="field" style="margin-top:14px"><label>Legenda para as novas fotos (opcional)</label><input name="caption" maxlength="60" placeholder="Time 1, Time 2 ou Craque do dia"></div><div class="note">Você pode manter, remover ou acrescentar imagens. Até quatro fotos, compactadas e guardadas no Firestore, sem ativar o Storage.</div>`);document.querySelector('#modalForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,files=[...form.elements.images.files],remove=[...form.querySelectorAll('[name="removePhoto"]:checked')].map(input=>input.value),remaining=existing.filter(photo=>!remove.includes(photo.id));if(files.length+remaining.length>4){toast(`Há espaço para ${4-remaining.length} nova(s) foto(s).`);return}try{for(const id of remove)await deleteRecord('gameGallery',id);for(let i=0;i<files.length;i++){const image=await resizeImage(files[i]),id=`${game.id}-${Date.now()}-${i}`;await saveRecord('gameGallery',{id,gameId:game.id,image,caption:form.elements.caption.value.trim()||files[i].name.replace(/\.[^.]+$/,''),createdAt:new Date().toISOString()})}closeModal();toast('Galeria atualizada.')}catch(error){toast(error.message||'Não foi possível salvar as fotos. Verifique as regras do Firestore.')}}}
function adminAwardPanel(game){const ballot=awardBallots.find(row=>row.gameId===game.id)||buildAwardBallot(game),status=voteWindowStatus(ballot),photos=gamePhotos(game.id),times=Object.values(ballot.teams||{});return `<section class="panel award-admin-panel"><div class="panel-head"><div><div class="eyebrow">DESTAQUES DA RODADA</div><h3>Craques do dia</h3></div><span class="pill ${status==='closed'?'done':status==='open'?'open':'pending'}">${status==='closed'?'Votação encerrada':status==='open'?'Votação aberta':'Aguardando horário'}</span></div><p class="sub">Jogadores e goleiros marcados como presentes votam em um nome de cada time. A votação abre ${new Date(ballot.opensAtMs).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} e encerra ${new Date(ballot.closesAtMs).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}.</p><div class="award-results">${times.map(team=>{const counts=team.candidates.map(c=>({...c,count:ballotVotesFor(ballot,team.id).filter(v=>v.candidatePlayerId===c.id).length}));const winners=status==='closed'?winningCandidates(ballot,team.id):[];return `<article class="award-result"><h4>${esc(team.name)}</h4>${status==='closed'?winners.length?winners.map(w=>`<div class="winner-line">🏆 <b>${esc(w.name)}</b> · ${w.votes} voto(s)</div>`).join(''):'<div class="subcell">Sem votos computados.</div>':counts.length?counts.map(c=>`<div class="subcell">${esc(c.name)}${c.goalkeeper?' · goleiro':''} · ${status==='closed'?c.count+' voto(s)':'candidato presente'}</div>`).join(''):'<div class="subcell">Marque os presentes e defina a escalação.</div>'}</article>`}).join('')}</div><div class="panel-head" style="margin:17px 0 9px"><h3>Fotos dos times e dos craques</h3><button class="btn small" data-action="edit-game-photos" data-id="${esc(game.id)}">${photos.length?`Gerenciar fotos (${photos.length}/4)`:'＋ Adicionar fotos'}</button></div>${galleryMarkup(game.id)}<div class="note">Confirme quem está presente em Lista. A janela é calculada automaticamente: 30 minutos após o início até 15 minutos depois do fim da sessão.</div></section>`}
function playerAwardPanel(game){const root='<div id="player-award-root"></div>';if(!game)return root;const ballot=awardBallots.find(row=>row.gameId===game.id);if(!ballot)return root;const status=voteWindowStatus(ballot),canVote=ballot.eligibleVoterIds.includes(currentUser?.uid),photos=gamePhotos(game.id);let body='';if(status==='before')body=`<div class="note">A votação abre às ${new Date(ballot.opensAtMs).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} (30 minutos após o início do jogo).</div>`;else if(status==='open'&&!canVote)body='<div class="note">Somente jogadores e goleiros com presença confirmada pelo administrador podem votar.</div>';else if(status==='open')body=`<p class="sub">Escolha um craque de cada time. Toque no nome; o botão de voto aparecerá em seguida.</p><div class="award-results">${Object.values(ballot.teams||{}).map(team=>{const voteId=`${game.id}-${team.id}-${currentUser.uid}`,already=awardVotes.some(v=>v.id===voteId),selected=selectedAwardCandidates[`${game.id}:${team.id}`];return `<article class="award-result"><h4>${esc(team.name)}</h4><div class="award-candidates">${team.candidates.map(candidate=>`<button class="candidate-chip ${selected===candidate.id?'selected':''}" data-action="choose-award-candidate" data-game="${esc(game.id)}" data-team="${esc(team.id)}" data-candidate="${esc(candidate.id)}" ${already?'disabled':''}>${esc(candidate.name)}${candidate.goalkeeper?' · goleiro':''}</button>`).join('')||'<span class="subcell">Não há candidatos presentes neste time.</span>'}</div>${already?'<span class="pill paid">Voto registrado ✓</span>':selected?`<button class="btn primary small" data-action="submit-award-vote" data-game="${esc(game.id)}" data-team="${esc(team.id)}" data-candidate="${esc(selected)}">Votar neste craque</button>`:''}</article>`}).join('')}</div><div class="subcell">A votação fecha às ${new Date(ballot.closesAtMs).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}.</div>`;else body=`<div class="award-results">${Object.values(ballot.teams||{}).map(team=>{const winners=winningCandidates(ballot,team.id);return `<article class="award-result"><h4>${esc(team.name)} · resultado final</h4>${winners.length?winners.map(w=>`<div class="winner-line">🏆 <b>${esc(w.name)}</b> · ${w.votes} voto(s)</div>`).join(''):'<div class="subcell">Sem votos computados.</div>'}</article>`}).join('')}</div>`;return `<div id="player-award-root"><section class="panel player-award-panel"><div class="panel-head"><div><div class="eyebrow">ESCOLHA DA RODADA</div><h3>Craques do dia</h3></div><span class="pill ${status==='closed'?'done':status==='open'?'open':'pending'}">${status==='closed'?'Resultado final':status==='open'?'Votação aberta':'Em breve'}</span></div>${body}${photos.length?`<h4 class="gallery-heading">Fotos do jogo</h4>${galleryMarkup(game.id)}`:''}</section></div>`}
function refreshPlayerAwardPanel(){const root=document.querySelector('#player-award-root');if(!root)return;const data=currentPlayerData,game=(data?.games||[]).find(g=>g.date===today)||((data?.games||[]).find(g=>g.id===upcoming()?.id));root.outerHTML=playerAwardPanel(game)}
function watchAwardData(){stopAwardBallotListener?.();stopAwardVoteListener?.();stopGalleryListener?.();stopAwardBallotListener=listenToRecords('gameAwardBallots',rows=>{awardBallots=rows;if(currentUser?.role==='player')refreshPlayerAwardPanel();else if(page==='dashboard')render()},()=>toast('Não foi possível carregar a votação. Publique as regras atualizadas do Firestore.'));stopAwardVoteListener=listenToRecords('gameAwardVotes',rows=>{awardVotes=rows;if(currentUser?.role==='player')refreshPlayerAwardPanel();else if(page==='dashboard')render()},()=>toast('Não foi possível atualizar a contagem dos votos.'));stopGalleryListener=listenToRecords('gameGallery',rows=>{gameGallery=rows;if(currentUser?.role==='player')refreshPlayerAwardPanel();else if(page==='dashboard')render()},()=>toast('Não foi possível carregar as fotos do jogo.'))}
function noticeForm(item={}){openModal(item.id?'Editar aviso':'Novo aviso',`<div class="form-grid"><div class="field full"><label>Título *</label><input name="title" required value="${esc(item.title||'')}"></div><div class="field full"><label>Texto *</label><textarea name="message" rows="5" required>${esc(item.message||'')}</textarea></div><div class="field"><label>Remover após</label><input name="expiresAt" type="date" value="${item.expiresAt||''}"></div><div class="field"><label>Imagens (máximo 2)</label><input name="images" type="file" accept="image/*" multiple></div></div><div class="note">Imagens são compactadas e salvas no Firestore do plano Spark; cada aviso aceita até 2 imagens.</div>`);document.querySelector('#modalForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,files=[...form.elements.images.files];if(files.length>2){toast('Escolha no máximo duas imagens.');return}try{const added=await Promise.all(files.map(resizeImage));const d=Object.fromEntries(new FormData(form));const rec={id:item.id||`notice-${Date.now()}`,title:d.title.trim(),message:d.message.trim(),expiresAt:d.expiresAt,images:added.length?added:(item.images||[]),createdAt:item.createdAt||new Date().toISOString()};await saveRecord('notices',rec);notices=[...notices.filter(x=>x.id!==rec.id),rec];persistRecords('notices',notices);closeModal();render();toast('Aviso salvo.')}catch(err){toast(err.message||'Não foi possível guardar as imagens.')}}}
async function removeExpiredNotices(){for(const n of notices)if(n.expiresAt&&n.expiresAt<today&&!expiredNoticeDeletes.has(n.id)){expiredNoticeDeletes.add(n.id);try{await deleteRecord('notices',n.id)}catch{}}}
function settingsPage(){return `${heading('ADMINISTRAÇÃO','Configurações','Edite a chave PIX e os valores padrão usados ao cadastrar novos jogos.',`<button class="btn primary" data-action="save-settings">Salvar alterações</button>`)}<div class="grid-2"><div class="panel"><div class="panel-head"><h3>Pagamento via PIX</h3></div><div class="field"><label>Chave PIX (telefone)</label><input id="pix" type="tel" inputmode="numeric" value="${esc(formatPix(state.pix))}"></div><div class="field" style="margin-top:12px"><label>Instrução padrão</label><input value="Enviar comprovante ao administrador após o PIX" disabled></div></div><div class="panel"><div class="panel-head"><h3>Valores padrão (R$)</h3></div><div class="field"><label>Valor do jogo</label><input id="default-game-fee" type="number" min="0" step="0.01" value="${Number(state.gameFee??20).toFixed(2)}"></div><div class="field" style="margin-top:12px"><label>Churrasco</label><input id="default-food-fee" type="number" min="0" step="0.01" value="${Number(state.foodFee??7).toFixed(2)}"></div><p class="sub" style="margin-top:10px">Esses valores preenchem novos jogos. Você pode ajustar cada jogo individualmente.</p></div><div class="panel"><div class="panel-head"><h3>Sincronização</h3></div><p class="sub">${cloudEnabled?'Login do administrador conectado. Os dados de jogos e pagamentos sincronizam pelo Firestore.':'O projeto abre em modo demonstração e salva os dados neste navegador.'}</p><div class="note">O sistema não usa Firebase Storage. Comprovantes anexados ficam somente neste dispositivo; os registros de pagamento e demais dados continuam sincronizados pelo Firestore.</div><p class="sub" style="margin-top:14px">O plano Spark permanece sem configuração de faturamento. Comprovantes podem ser anexados em imagem ou PDF de até 5 MB.</p></div><div class="panel"><div class="panel-head"><h3>Campos de futebol</h3></div><p class="sub">Edite endereços e links na seção Gramados. Locais cadastrados: ${state.fields.length}.</p></div></div><div class="panel" style="margin-top:15px"><div class="panel-head"><h3>Dados do sistema</h3></div><p class="sub">${state.players.length} participantes · ${state.fields.length} gramados · ${state.games.length} jogos históricos e futuros.</p><button class="btn" data-action="reset-demo">Restaurar dados iniciais desta versão</button></div>`}
function openModal(title,body,submitLabel='Salvar'){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" data-close><form class="modal" id="modalForm"><div class="modal-head"><h2>${title}</h2><button type="button" class="close" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="btn" data-close>Cancelar</button><button type="submit" class="btn primary">${submitLabel}</button></div></form></div>`}
function closeModal(){document.querySelector('#modal-root').innerHTML=''}
function toast(msg){const root=document.querySelector('#toast-root');root.innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>root.innerHTML='',2800)}
function gameForm(g={}){const isEdit=!!g.id;openModal(isEdit?'Editar jogo':'Agendar jogo',`<div class="form-grid"><div class="field"><label>Data *</label><input name="date" type="date" required value="${g.date||''}"></div><div class="field"><label>Horário *</label><input name="time" type="time" required value="${g.time||'19:30'}"></div><div class="field"><label>Gramado</label><select name="fieldId">${state.fields.map(f=>`<option value="${f.id}" ${g.fieldId===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select><button type="button" class="btn small" id="add-game-field">＋ Novo gramado</button></div><div class="field full" id="game-field-quick" hidden><div class="form-grid"><div class="field full"><label>Nome do novo gramado *</label><input id="game-new-field-name" placeholder="Ex.: Campo São João Futebol Clube"></div><div class="field full"><label>Endereço / referência</label><input id="game-new-field-address"></div><div class="field full"><label>Link do Google Maps</label><input id="game-new-field-maps" type="url"></div><div class="field full"><label>Link do Waze</label><input id="game-new-field-waze" type="url"></div><div class="field full"><button type="button" class="btn" id="save-game-field">Salvar e selecionar gramado</button></div></div></div><div class="field"><label>Valor do jogo (R$)</label><input name="fee" type="number" min="0" step="0.01" value="${g.fee??state.gameFee??20}"></div><div class="field"><label>Extra / churrasco (R$)</label><input name="foodFee" type="number" min="0" step="0.01" value="${g.foodFee??state.foodFee??7}"></div><div class="field"><label>Nome do extra</label><input name="foodName" value="${esc(g.foodName||'Churrasco')}"></div><div class="field"><label>Tempo total da sessão (minutos)</label><input name="durationMinutes" type="number" min="1" step="1" value="${g.durationMinutes??60}"></div><div class="field"><label>Tempo de cada partida/intervalo (minutos)</label><input name="matchIntervalMinutes" type="number" min="1" step="1" value="${g.matchIntervalMinutes??8}"></div><div class="field"><label>Status</label><select name="status"><option value="open" ${g.status==='open'?'selected':''}>Inscrições abertas</option><option value="closed" ${g.status==='closed'?'selected':''}>Lista fechada</option><option value="played" ${g.status==='played'?'selected':''}>Realizado</option></select></div><div class="field full"><label>Se chover: data</label><input name="rainDate" type="date" value="${g.rainDate||''}"></div><div class="field"><label>Horário alternativo</label><input name="rainTime" type="time" value="${g.rainTime||'14:30'}"></div><div class="field"><label>Campo alternativo</label><select name="rainFieldId"><option value="">Escolha o campo</option>${state.fields.map(f=>`<option value="${f.id}" ${(g.rainFieldId||'field-arena-andrino')===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div></div>`);
 const addFieldButton=document.querySelector('#add-game-field'),quickField=document.querySelector('#game-field-quick');addFieldButton.onclick=()=>{quickField.hidden=!quickField.hidden;if(!quickField.hidden)document.querySelector('#game-new-field-name').focus()};document.querySelector('#save-game-field').onclick=()=>{const name=document.querySelector('#game-new-field-name').value.trim();if(!name){toast('Informe o nome do gramado.');return}const form=document.querySelector('#modalForm'),draft={...g,...Object.fromEntries(new FormData(form))},existing=state.fields.find(f=>playerKey(f.name)===playerKey(name));if(existing){draft.fieldId=existing.id;gameForm(draft);toast('Já cadastrado. O gramado existente foi selecionado.');return}const created={id:'field-quick-'+Date.now(),name,address:document.querySelector('#game-new-field-address').value.trim(),maps:document.querySelector('#game-new-field-maps').value.trim(),waze:document.querySelector('#game-new-field-waze').value.trim(),notes:''};state.fields.push(created);persist();gameForm({...draft,fieldId:created.id});toast('Gramado cadastrado e selecionado.')};
 document.querySelector('#modalForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)),numbers={fee:+d.fee,foodFee:+d.foodFee,durationMinutes:+d.durationMinutes||60,matchIntervalMinutes:+d.matchIntervalMinutes||8};if(isEdit)Object.assign(g,d,numbers,{scheduleTemplate:false});else state.games.push({...d,...numbers,id:'g'+Date.now(),players:[],teams:structuredClone(defaultTeams),maps:'',status:d.status,scheduleTemplate:false});persist();closeModal();render();toast('Jogo salvo.')}
}
function syncPlayerNameReferences(player,oldNames=[]){const keys=new Set(oldNames.filter(Boolean).map(playerKey));for(const game of state.games){for(const entry of game.players||[])if(entry.playerId===player.id||keys.has(playerKey(entry.name))){entry.playerId=player.id;entry.name=player.name}for(const team of game.teams||[]){const ids=Array.isArray(team.playerIds)?team.playerIds:[];const names=team.players||[];const matched=ids.includes(player.id)||names.some(name=>keys.has(playerKey(name)));if(matched){const nextIds=new Set(ids);nextIds.add(player.id);team.playerIds=[...nextIds];team.players=names.map(name=>keys.has(playerKey(name))?player.name:name);if(ids.includes(player.id)&&!team.players.includes(player.name))team.players.push(player.name)}if(keys.has(playerKey(team.goalkeeper))||team.goalkeeper===player.id)team.goalkeeper=player.name}}}
function playerForm(p={}){openModal(p.id?'Editar participante':'Novo participante',`<div class="form-grid"><div class="field full"><label>Nome ou nome completo *</label><input name="name" required value="${esc(p.name||'')}"></div><div class="field"><label>Apelido</label><input name="nickname" value="${esc(p.nickname||'')}"></div><div class="field"><label>Telefone / WhatsApp</label><input name="phone" placeholder="(48) 99999-9999" value="${esc(p.phone||'')}"></div><div class="field"><label>Status</label><select name="active"><option value="true" ${p.active!==false?'selected':''}>Ativo</option><option value="false" ${p.active===false?'selected':''}>Inativo</option></select></div></div><div class="note">Os nomes foram pré-cadastrados a partir das listas de jogos. Complete os dados quando estiverem disponíveis.</div>`);document.querySelector('#modalForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(p.id){const newPhone=d.phone.trim(),duplicate=state.players.find(existing=>existing.id!==p.id&&newPhone&&existing.phone&&playerPhoneMatches(existing.phone,newPhone));if(duplicate){toast('Já cadastrado. Este celular já está vinculado a '+duplicate.name+'.');return}const oldName=p.name;Object.assign(p,d,{name:d.name.trim(),nickname:d.nickname.trim(),phone:newPhone,active:d.active==='true'});syncPlayerNameReferences(p,[oldName,...(p.aliases||[])]);}else{const newName=d.name.trim(),newPhone=phoneDigits(d.phone),duplicate=state.players.find(existing=>playerKey(existing.name)===playerKey(newName)||(newPhone&&existing.phone&&playerPhoneMatches(existing.phone,newPhone)));if(duplicate){toast('Já cadastrado. Este nome ou celular já está vinculado a '+duplicate.name+'. Edite o cadastro existente.');return}const player={...d,name:newName,nickname:d.nickname.trim(),phone:d.phone.trim(),id:'p'+Date.now(),active:d.active==='true'};state.players.push(player);if(player.active)ensurePlayerInUpcomingGame(player)}persist();closeModal();render();toast('Participante salvo.')};}
function fieldForm(f={}){openModal(f.id?'Editar gramado':'Novo gramado',`<div class="form-grid"><div class="field full"><label>Nome do local *</label><input name="name" required value="${esc(f.name||'')}"></div><div class="field full"><label>Endereço / referência</label><input name="address" value="${esc(f.address||'')}"></div><div class="field full"><label>Link do Google Maps</label><input name="maps" value="${esc(f.maps||'')}"></div><div class="field full"><label>Link do Waze</label><input name="waze" value="${esc(f.waze||'')}"></div><div class="field full"><label>Observações</label><textarea name="notes" rows="3">${esc(f.notes||'')}</textarea></div></div>`);document.querySelector('#modalForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(f.id)Object.assign(f,d);else state.fields.push({...d,id:'f'+Date.now()});persist();closeModal();render();toast('Gramado salvo.')};}
function roster(g){
 rosterGame=g.id;const fieldCount=()=>g.players.filter(p=>p.position!=='Goleiro').length,keeperCount=()=>g.players.filter(p=>p.position==='Goleiro').length,teamCount=()=>fieldCount()>=18?3:2,atLimit=fieldCount()>=21&&keeperCount()>=teamCount(),body=`<div class="toolbar"><select id="add-player" class="search" ${atLimit?'disabled':''}><option value="">Adicionar participante cadastrado…</option>${state.players.filter(p=>p.active&&!g.players.some(x=>x.playerId===p.id||x.name.toLowerCase()===p.name.toLowerCase())).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}${p.nickname?` · ${esc(p.nickname)}`:''}</option>`).join('')}</select><select id="new-player-position" class="search" aria-label="Posição"><option value="Jogador">Jogador de linha</option><option value="Goleiro">Goleiro</option></select><button class="btn" type="button" id="addToRoster" ${atLimit?'disabled':''}>＋ Adicionar</button></div><div class="note">${fieldCount()} jogadores de linha + ${keeperCount()} goleiros. Com 18 a 21 jogadores de linha, habilita até 3 times; cada goleiro é contabilizado à parte. Limite: 21 jogadores de linha e 1 goleiro por time.</div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Disponibilidade</th><th>Presença no jogo</th><th>Posição</th><th>Pagamento</th><th>Extra</th><th></th></tr></thead><tbody>${g.players.map((p,i)=>`<tr><td class="name-cell">${gameTeamIndex(g,p)>=0?`<span class="team-chip team-color-${gameTeamIndex(g,p)+1}">${esc(g.teams[gameTeamIndex(g,p)]?.name||`TIME 0${gameTeamIndex(g,p)+1}`)}</span>`:`<span class="team-chip team-color-waiting">Aguardando time</span>`}<br>${esc(p.name)}</td><td><select data-attendance="${i}" class="inline-select"><option value="friday" ${(p.attendance||'friday')==='friday'?'selected':''}>Sexta · 19h30</option><option value="saturday" ${p.attendance==='saturday'?'selected':''}>Somente sábado</option></select></td><td><label class="presence-toggle"><input type="checkbox" data-present="${i}" ${p.present?'checked':''}> Presente</label></td><td><select data-pos="${i}" class="inline-select"><option ${p.position==='Jogador'?'selected':''}>Jogador</option><option ${p.position==='Goleiro'?'selected':''}>Goleiro</option></select></td><td><button class="pill ${p.position==='Goleiro'?'done':p.paid?'paid':'pending'}" ${p.position==='Goleiro'?'':'data-action="toggle-pay" data-id="'+g.id+'" data-index="'+i+'"'}>${p.position==='Goleiro'?'Isento':p.paid?'Pago':'Pendente'}</button></td><td>${g.foodFee?(p.foodWanted?`<button class="pill ${p.foodPaid?'paid':'pending'}'" data-action="toggle-food" data-id="${g.id}" data-index="${i}">🥩 ${p.foodPaid?'Pago':'Pendente'}</button>`:`<button class="btn small" data-action="toggle-food-order" data-id="${g.id}" data-index="${i}">Não pediu · Incluir</button>`):'—'}</td><td><button class="copy" data-action="remove-player" data-id="${g.id}" data-index="${i}">Remover</button></td></tr>`).join('')}</tbody></table></div>`;
 openModal(`Lista · ${localDate(g.date)} · ${esc(field(g.fieldId)?.name||'Jogo')}`,body,'Concluir');document.querySelector('#modalForm').onsubmit=e=>{e.preventDefault();g.rosterEdited=true;const next=nextWeeklyGame(g);let copied=false;if(next&&!next.rosterEdited){next.players=g.players.map(p=>({...p,paid:false,paidAt:'',foodPaid:false,foodPaidAt:'',receipt:'',present:false}));next.rosterSuggestedFrom=g.id;copied=true}persist();closeModal();render();toast(copied?'Lista atualizada e copiada como sugestão para a próxima semana.':'Lista atualizada.')};
 document.querySelector('#addToRoster').onclick=()=>{const player=state.players.find(p=>p.id===document.querySelector('#add-player').value),position=document.querySelector('#new-player-position').value;if(!player||g.players.some(p=>p.playerId===player.id||p.name.toLowerCase()===player.name.toLowerCase()))return;if(position==='Goleiro'&&keeperCount()>=teamCount()){toast(`O limite atual é ${teamCount()} goleiros.`);return}if(position!=='Goleiro'&&fieldCount()>=21){toast('O limite é 21 jogadores de linha.');return}g.players.push({name:player.name,playerId:player.id,position,attendance:'friday',present:false,paid:false,foodWanted:false,foodPaid:false});addPlayerToSuggestedTeam(g,player,position);if(fieldCount()>=18&&g.teams.length<3)g.teams.push(structuredClone(thirdTeamTemplate));roster(g)};
 document.querySelectorAll('[data-pos]').forEach(sel=>sel.onchange=()=>{const player=g.players[Number(sel.dataset.pos)],oldPosition=player.position,nextPosition=sel.value;if(nextPosition==='Goleiro'&&keeperCount()>=teamCount()){toast(`O limite atual é ${teamCount()} goleiros.`);sel.value=player.position;return}if(nextPosition!=='Goleiro'&&fieldCount()>=21){toast('O limite é 21 jogadores de linha.');sel.value=player.position;return}player.position=nextPosition;if(nextPosition==='Goleiro'){player.paid=false;player.paidAt=''}for(const team of g.teams||[]){if(nextPosition==='Goleiro'){team.playerIds=(team.playerIds||[]).filter(id=>id!==player.playerId);team.players=(team.players||[]).filter(name=>playerKey(name)!==playerKey(player.name));if(!team.goalkeeper){team.goalkeeper=player.name;break}}else if(oldPosition==='Goleiro'&&playerKey(team.goalkeeper)===playerKey(player.name))team.goalkeeper=''}if(nextPosition!=='Goleiro'&&oldPosition==='Goleiro'){const person=state.players.find(item=>item.id===player.playerId)||findTeamPlayer(player.name);addPlayerToSuggestedTeam(g,person,'Jogador')}if(fieldCount()<18&&g.teams.length>2){g.teamsEdited=false;autoDistributeGameTeams(g)}else if(!g.teamsEdited)autoDistributeGameTeams(g);persist();roster(g)});
 document.querySelectorAll('[data-present]').forEach(box=>box.onchange=()=>{g.players[Number(box.dataset.present)].present=box.checked;persist();roster(g);toast(box.checked?'Presença confirmada.':'Presença removida.')});document.querySelectorAll('[data-attendance]').forEach(sel=>sel.onchange=()=>{g.players[Number(sel.dataset.attendance)].attendance=sel.value;persist();toast('Disponibilidade registrada.')})
}
function paymentForm(g,i){
 const p=g.players[i],isGoalkeeper=p.position==='Goleiro';
 openModal(`Pagamento · ${esc(p.name)}`,`<div class="form-grid"><div class="field"><label>Taxa do jogo</label><input value="${isGoalkeeper?'Isento · goleiro':brl(g.fee)}" disabled></div>${isGoalkeeper?'<div class="field"><label>Pagamento do jogo</label><input value="Isento" disabled></div>':`<div class="field"><label>Status do jogo</label><select name="paid"><option value="false" ${!p.paid?'selected':''}>Pendente</option><option value="true" ${p.paid?'selected':''}>Pago</option></select></div>`}${g.foodFee?`<div class="field"><label>Vai querer ${esc(g.foodName||'extra')}? · ${brl(g.foodFee)}</label><select name="foodWanted"><option value="false" ${!p.foodWanted?'selected':''}>Não pediu</option><option value="true" ${p.foodWanted?'selected':''}>Sim, incluir</option></select></div><div class="field"><label>Pagamento do extra</label><select name="foodPaid"><option value="false" ${!p.foodPaid?'selected':''}>Pendente</option><option value="true" ${p.foodPaid?'selected':''}>Pago</option></select></div>`:''}<div class="field full"><label>Comprovante (imagem ou PDF, até 5 MB)</label><input name="receipt" type="file" accept="image/*,application/pdf"></div>${p.receipt?`<div class="field full">${receiptCell(p)}<button type="button" class="copy" data-action="remove-receipt" data-id="${g.id}" data-index="${i}">Remover comprovante</button></div>`:''}</div><div class="note">O goleiro é isento da taxa do jogo. O churrasco é opcional e cobrado à parte.</div>`);
 document.querySelector('#modalForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,wasPaid=!!p.paid,wasFoodPaid=!!p.foodPaid;p.paid=isGoalkeeper?false:form.elements.paid.value==='true';p.paidAt=p.paid?(wasPaid?(p.paidAt||new Date().toISOString()):new Date().toISOString()):'';if(form.elements.foodWanted)p.foodWanted=form.elements.foodWanted.value==='true';if(form.elements.foodPaid)p.foodPaid=p.foodWanted&&form.elements.foodPaid.value==='true';p.foodPaidAt=p.foodPaid?(wasFoodPaid?(p.foodPaidAt||new Date().toISOString()):new Date().toISOString()):'';const file=form.elements.receipt.files[0];if(file){if(!file.type.startsWith('image/')&&file.type!=='application/pdf'){toast('Escolha uma imagem ou um PDF.');return}try{const key=await saveLocalReceipt(file);p.receipt='localreceipt:'+key}catch(error){toast(error.message||'Não foi possível guardar o arquivo neste dispositivo.');return}}persist();closeModal();render();toast('Pagamento atualizado.')};
}
function exportCsv(){const lines=['Data,Horário,Jogo,Participante,Jogo pago,Extra pago,Valor do jogo,Valor extra'];state.games.forEach(g=>g.players.forEach(p=>lines.push([g.date,g.time,field(g.fieldId)?.name||'',p.name,p.position==='Goleiro'?'Isento':p.paid?'Sim':'Não',p.foodPaid?'Sim':'Não',g.fee,g.foodFee||0].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(','))));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}));a.download='pagamentos-futebol-society.csv';a.click();URL.revokeObjectURL(a.href);}

