 if(e.target.closest('#menuBtn')){document.querySelector('#sidebar').classList.toggle('open');return}
 if(e.target.matches('.modal-backdrop')||e.target.closest('button[data-close]')){closeModal();return}
 const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id,g=state.games.find(x=>x.id===id),i=Number(b.dataset.index),p=state.players.find(x=>x.id===id),f=state.fields.find(x=>x.id===id);
 if(act==='activate-all-players'){activateAllPlayerAccounts();return}
